recipes.code:
{
  "inputs": [
    {
      "id": "nordic-data-key",
      "type": "promptString",
      "description": "Your Nordic Data API key. Free signup: nordicdata.cloud. Sandbox: sandbox_try_2026 (30/hr).",
      "password": true
    }
  ],
  "servers": {
    "nordic-data": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@nordic-data/mcp@0.1.1"
      ],
      "env": {
        "NORDIC_DATA_KEY": "${input:nordic-data-key}"
      }
    }
  }
}
